    "install": {
      "runtime-versions": {
        "nodejs": "20"
      },
      "commands": [
        "cd frontend",
        "npm ci"
      ]
    },
    "build": {
      "commands": [
        "echo \"=== FE commit: tsc, lint, unit tests, build ===\"",
        "npx tsc --noEmit",
        "npm run lint",
        "npm run test -- --run",
        "npm run build"
      ]
    }
  },
  "artifacts": {
    "base-directory": "frontend/dist",
    "files": [
      "**/*"
    ]
  }
}

